export function getSegmentKey(serviceKey, turnoverKey) {
  return `${serviceKey}|${turnoverKey ?? 'all'}`;
}

export function getClientSegment(selectedCard) {
  return clientSegmentData[getSegmentKey(selectedCard.serviceKey, selectedCard.turnoverKey)] ?? null;
}

export function getClientSegmentLeads(selectedCard, dataKey) {
  return getClientSegment(selectedCard)?.leads?.[dataKey] ?? [];
}
